def find_kth(arr1, arr2, k):
    def kth_element(a, b, k):
        if not a:
            return b[k - 1]
        if not b:
            return a[k - 1]
        if k == 1:
            return min(a[0], b[0])

        mid_a = len(a) // 2
        mid_b = len(b) // 2

        if mid_a + mid_b < k - 1:
            if a[mid_a] > b[mid_b]:
                return kth_element(a, b[mid_b + 1:], k - mid_b - 1)
            else:
                return kth_element(a[mid_a + 1:], b, k - mid_a - 1)
        else:
            if a[mid_a] > b[mid_b]:
                return kth_element(a[:mid_a], b, k)
            else:
                return kth_element(a, b[:mid_b], k)

    return kth_element(arr1, arr2, k)

# Example usage:
assert find_kth([2, 3, 6, 7, 9], [1, 4, 8, 10], 5) == 6
