def get_pairs_count(numbers, target_sum):
    count = 0
    freq = {}

    # Count occurrences of each number in the list
    for number in numbers:
        if number in freq:
            freq[number] += 1
        else:
            freq[number] = 1

    # Iterate through each number and find pairs
    for number in numbers:
        complement = target_sum - number
        if complement in freq:
            count += freq[complement]

        # If complement and number are the same, we should decrease the count by one
        if complement == number:
            count -= 1

    # Each pair is counted twice, so divide the count by 2
    return count // 2

# Example test
assert get_pairs_count([1, 1, 1, 1], 2) == 6
```

