def merge_dictionaries_three(dict1, dict2, dict3):
    """
    Merges three dictionaries into a single dictionary.
    If there are duplicate keys, the value from the last dictionary takes precedence.
    """
    # Merge dictionaries in the order such that the last one overrides previous values
    merged_dict = dict1.copy()  # Start with dict1
    merged_dict.update(dict2)   # Merge dict2
    merged_dict.update(dict3)   # Merge dict3
    return merged_dict

